// Recebe os clientes do Webhook e o CSV de investimentos e devolve 1 item por cliente
// com os produtos do perfil dele que cabem no saldo.
const clientes = $('Webhook').first().json.body.clientes || [];
const csv = $('Baixar Investimentos').first().json.data || '';

// "R$ 12.500,00" -> 12500
const paraNumero = (texto) =>
  Number(String(texto).replace(/[^\d,]/g, '').replace(',', '.')) || 0;

const [cabecalho, ...linhas] = csv.trim().split(/\r?\n/);
const campos = cabecalho.split(',').map((c) => c.trim());
const investimentos = linhas.map((linha) => {
  const valores = linha.split(',');
  const item = Object.fromEntries(campos.map((c, i) => [c, (valores[i] || '').trim()]));
  item.minimo = paraNumero(item.minimo);
  return item;
});

return clientes.map((cliente) => {
  const saldo = paraNumero(cliente.saldo);
  const doPerfil = investimentos
    .filter((inv) => inv.perfil.toLowerCase() === String(cliente.perfil).toLowerCase())
    .sort((a, b) => a.minimo - b.minimo);
  const elegiveis = doPerfil.filter((inv) => inv.minimo <= saldo);
  // Se o saldo não cobre nenhum mínimo, sugere o de menor aporte do perfil.
  const sugeridos = elegiveis.length ? elegiveis : doPerfil.slice(0, 1);

  return {
    json: {
      nome: cliente.nome,
      primeiroNome: String(cliente.nome).split(' ')[0],
      email: cliente.email,
      perfil: cliente.perfil,
      saldo: cliente.saldo,
      saldoNumero: saldo,
      produtos: sugeridos,
      produtosTexto: sugeridos
        .map((p) => `${p.produto} (mínimo R$ ${p.minimo.toLocaleString('pt-BR')}, rentabilidade ${p.rentabilidade})`)
        .join('; '),
      saldoCobreMinimo: elegiveis.length > 0,
    },
  };
});

